24	/**
25	 * Normalizes an optional submitted email to its canonical stored form: a syntactically
26	 * valid address, lower-cased. An absent (null) email is left as {@code null}.
27	 */
28	@Component
29	public class EmailNormalizer {
30	
31	    /**
32	     * A pragmatic syntactic check: a non-empty local part, an {@code @}, and a domain
33	     * containing at least one dot, with no whitespace or stray {@code @} characters.
34	     */
35	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
36	
37	    /**
38	     * @param email the raw submitted email (may be {@code null})
39	     * @return {@code null} if the input is {@code null}; otherwise the address lower-cased
40	     * @throws InvalidEmailException if the value is present but not a syntactically valid address
41	     */
42	    public String normalize(String email) {
43	        if (email == null) {
44	            return null;
45	        }
46	        if (!EMAIL.matcher(email).matches()) {
47	            throw new InvalidEmailException(email);
48	        }
49	        return email.toLowerCase(Locale.ROOT);
50	    }
51	}
