52	/**
53	 * Global Exception handler for REST controllers.
54	 * <p>
55	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
56	 *
57	 * @author Vitaliy Fedoriv
58	 * @author Alexander Dudkin
59	 */
60	@ControllerAdvice
61	public class ExceptionControllerAdvice {
62	
63	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
64	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
65	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
66	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
67	
68	    private final OwnerFieldsValidator ownerFieldsValidator;
69	
70	    public ExceptionControllerAdvice(OwnerFieldsValidator ownerFieldsValidator) {
71	        this.ownerFieldsValidator = ownerFieldsValidator;
72	    }
73	
74	    /**
75	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
76	     * class.
77	     *
78	     * @param e     Object referring to the thrown exception.
79	     * @param status HTTP response status.
80	     * @param url URL request.
81	     */
82	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
83	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
84	        problemDetail.setType(URI.create(url.toString()));
85	        problemDetail.setTitle(e.getClass().getSimpleName());
86	        problemDetail.setDetail(detail);
87	        problemDetail.setProperty("timestamp", Instant.now());
88	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
89	        return problemDetail;
90	    }
91	
92	    /**
93	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
94	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
95	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
96	     * would catch it and report an authorization failure as a 500.
97	     *
98	     * @param e The {@link AccessDeniedException} to propagate
99	     * @throws AccessDeniedException always
100	     */
101	    @ExceptionHandler(AccessDeniedException.class)
102	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
103	        throw e;
104	    }
105	
106	    /**
107	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
108	     *
109	     * @param e The {@link Exception} to be handled
110	     * @param request {@link HttpServletRequest} object referring to the current request.
111	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
112	     */
113	    @ExceptionHandler(Exception.class)
114	    @ResponseBody
115	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
116	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
117	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
118	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
119	        return ResponseEntity.status(status).body(detail);
120	    }
121	
122	    /**
123	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
124	     * method returns a 404 Not Found status if an entity does not exist.
125	     *
126	     * @param e The {@link DataIntegrityViolationException} to be handled
127	     * @param request {@link HttpServletRequest} object referring to the current request.
128	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
129	     */
130	    @ExceptionHandler(DataIntegrityViolationException.class)
131	    @ResponseBody
132	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
133	        logger.warn("Data integrity violation at {} {}: {}",
134	            request.getMethod(),
135	            request.getRequestURI(),
136	            e.getMessage());
137	        logger.debug("Data integrity violation stacktrace", e);
138	        HttpStatus status = HttpStatus.NOT_FOUND;
139	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
140	        return ResponseEntity.status(status).body(detail);
141	    }
142	
143	    /**
144	     * Handles exception thrown by Bean Validation on controller methods parameters
145	     *
146	     * @param e The {@link MethodArgumentNotValidException} to be handled
147	     * @param request {@link HttpServletRequest} object referring to the current request.
148	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
149	     */
150	    @ExceptionHandler(MethodArgumentNotValidException.class)
151	    @ResponseBody
152	    public ResponseEntity<?> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
153	        HttpStatus status = HttpStatus.BAD_REQUEST;
154	        BindingErrorsResponse errors = new BindingErrorsResponse();
155	        BindingResult bindingResult = e.getBindingResult();
156	        if (bindingResult.getTarget() instanceof OwnerFieldsDto ownerFields) {
157	            List<String> missingFields = ownerFieldsValidator.findMissingOrBlankFields(ownerFields);
158	            if (!missingFields.isEmpty()) {
159	                return ResponseEntity.status(status).body(new ValidationErrorsResponse(missingFields));
160	            }
161	        }
162	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
163	        if (bindingResult.hasErrors()) {
164	            errors.addAllErrors(bindingResult);
165	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
166	                .map(fieldError -> {
167	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
168	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
169	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
170	                        fieldError.getField(),
171	                        defaultMessage,
172	                        rejectedValue);
173	                    return new ValidationMessageDto(message)
174	                        .putAdditionalProperty("field", fieldError.getField())
175	                        .putAdditionalProperty("rejectedValue", rejectedValue)
176	                        .putAdditionalProperty("defaultMessage", defaultMessage);
177	                })
178	                .toList();
179	            logger.debug("Validation error at {} {}: {}",
180	                request.getMethod(),
181	                request.getRequestURI(),
182	                bindingResult.getFieldErrors());
183	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
184	            return ResponseEntity.status(status).body(detail);
185	        }
186	        return ResponseEntity.status(status).body(detail);
187	    }
188	
189	    /**
190	     * Handles {@link MissingOwnerFieldsException} raised when an owner is created with required
191	     * fields that are missing or blank. Returns a 400 Bad Request whose {@code errors} array lists
192	     * the name of each offending field.
193	     *
194	     * @param e The {@link MissingOwnerFieldsException} to be handled
195	     * @return A {@link ResponseEntity} containing the offending field names and a 400 Bad Request status.
196	     */
197	    @ExceptionHandler(MissingOwnerFieldsException.class)
198	    @ResponseBody
199	    public ResponseEntity<ValidationErrorsResponse> handleMissingOwnerFieldsException(MissingOwnerFieldsException e) {
200	        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(new ValidationErrorsResponse(e.getFields()));
201	    }
202	
203	    /**
204	     * Handles {@link InvalidTelephoneException} raised when an owner's telephone does not
205	     * reduce to exactly ten digits. Returns a 400 Bad Request whose {@code errors} array
206	     * names the offending field.
207	     *
208	     * @param e The {@link InvalidTelephoneException} to be handled
209	     * @return A {@link ResponseEntity} containing the offending field name and a 400 Bad Request status.
210	     */
211	    @ExceptionHandler(InvalidTelephoneException.class)
212	    @ResponseBody
213	    public ResponseEntity<ValidationErrorsResponse> handleInvalidTelephoneException(InvalidTelephoneException e) {
214	        logger.debug("Invalid telephone: {}", e.getMessage());
215	        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
216	            .body(new ValidationErrorsResponse(List.of(InvalidTelephoneException.FIELD)));
217	    }
218	
219	    /**
220	     * Handles {@link InvalidEmailException} raised when an owner's email is present but is
221	     * not a syntactically valid address. Returns a 400 Bad Request whose {@code errors}
222	     * array names the offending field.
223	     *
224	     * @param e The {@link InvalidEmailException} to be handled
225	     * @return A {@link ResponseEntity} containing the offending field name and a 400 Bad Request status.
226	     */
227	    @ExceptionHandler(InvalidEmailException.class)
228	    @ResponseBody
229	    public ResponseEntity<ValidationErrorsResponse> handleInvalidEmailException(InvalidEmailException e) {
230	        logger.debug("Invalid email: {}", e.getMessage());
231	        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
232	            .body(new ValidationErrorsResponse(List.of(InvalidEmailException.FIELD)));
233	    }
234	
235	    /**
236	     * Handles {@link InvalidPostcodeException} raised when an owner's postcode is present but is
237	     * not four digits, or is out of range for the region of the owner's city. Returns a 400 Bad
238	     * Request whose {@code errors} array names the offending field.
239	     *
240	     * @param e The {@link InvalidPostcodeException} to be handled
241	     * @return A {@link ResponseEntity} containing the offending field name and a 400 Bad Request status.
242	     */
243	    @ExceptionHandler(InvalidPostcodeException.class)
244	    @ResponseBody
245	    public ResponseEntity<ValidationErrorsResponse> handleInvalidPostcodeException(InvalidPostcodeException e) {
246	        logger.debug("Invalid postcode: {}", e.getMessage());
247	        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
248	            .body(new ValidationErrorsResponse(List.of(InvalidPostcodeException.FIELD)));
249	    }
250	
251	    /**
252	     * Handles {@link FutureRegistrationDateException} raised when an owner is created with a
253	     * supplied registration date later than the server's current date. Returns a 400 Bad Request
254	     * whose {@code errors} array names the offending field.
255	     *
256	     * @param e The {@link FutureRegistrationDateException} to be handled
257	     * @return A {@link ResponseEntity} containing the offending field name and a 400 Bad Request status.
258	     */
259	    @ExceptionHandler(FutureRegistrationDateException.class)
260	    @ResponseBody
261	    public ResponseEntity<ValidationErrorsResponse> handleFutureRegistrationDateException(FutureRegistrationDateException e) {
262	        logger.debug("Future registration date: {}", e.getMessage());
263	        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
264	            .body(new ValidationErrorsResponse(List.of(FutureRegistrationDateException.FIELD)));
265	    }
266	
267	    /**
268	     * Handles {@link DuplicateIdentityException} raised when an owner is created whose whole
269	     * derived identity key already belongs to another owner. This is the single duplicate rule
270	     * that replaces the former separate telephone, email and household checks. Returns a 409
271	     * Conflict whose {@code errors} array names the offending field.
272	     *
273	     * @param e The {@link DuplicateIdentityException} to be handled
274	     * @return A {@link ResponseEntity} containing the offending field name and a 409 Conflict status.
275	     */
276	    @ExceptionHandler(DuplicateIdentityException.class)
277	    @ResponseBody
278	    public ResponseEntity<ValidationErrorsResponse> handleDuplicateIdentityException(DuplicateIdentityException e) {
279	        logger.debug("Duplicate identity: {}", e.getMessage());
280	        return ResponseEntity.status(HttpStatus.CONFLICT)
281	            .body(new ValidationErrorsResponse(List.of(DuplicateIdentityException.FIELD)));
282	    }
283	
284	    /**
285	     * Handles {@link HouseholdDuplicateException} raised when an owner is created into a household
286	     * (same last name and postcode) that already exists without declaring {@code sharesHousehold}.
287	     * Returns a 409 Conflict whose {@code errors} array names the offending field.
288	     *
289	     * @param e The {@link HouseholdDuplicateException} to be handled
290	     * @return A {@link ResponseEntity} containing the offending field name and a 409 Conflict status.
291	     */
292	    @ExceptionHandler(HouseholdDuplicateException.class)
293	    @ResponseBody
294	    public ResponseEntity<ValidationErrorsResponse> handleHouseholdDuplicateException(HouseholdDuplicateException e) {
295	        logger.debug("Household duplicate: {}", e.getMessage());
296	        return ResponseEntity.status(HttpStatus.CONFLICT)
297	            .body(new ValidationErrorsResponse(List.of(HouseholdDuplicateException.FIELD)));
298	    }
299	
300	    /**
301	     * Handles {@link CityOwnerLimitException} raised when an owner is created in a city that
302	     * already contains the maximum allowed number of owners. Returns a 409 Conflict whose
303	     * {@code errors} array names the offending field.
304	     *
305	     * @param e The {@link CityOwnerLimitException} to be handled
306	     * @return A {@link ResponseEntity} containing the offending field name and a 409 Conflict status.
307	     */
308	    @ExceptionHandler(CityOwnerLimitException.class)
309	    @ResponseBody
310	    public ResponseEntity<ValidationErrorsResponse> handleCityOwnerLimitException(CityOwnerLimitException e) {
311	        logger.debug("City owner limit reached: {}", e.getMessage());
312	        return ResponseEntity.status(HttpStatus.CONFLICT)
313	            .body(new ValidationErrorsResponse(List.of(CityOwnerLimitException.FIELD)));
314	    }
315	
316	    /**
317	     * Handles {@link DailyOwnerLimitException} raised when an owner is created on a day that has
318	     * already reached the maximum allowed number of owner registrations. Returns a 429 Too Many
319	     * Requests whose {@code errors} array names the offending field.
320	     *
321	     * @param e The {@link DailyOwnerLimitException} to be handled
322	     * @return A {@link ResponseEntity} containing the offending field name and a 429 status.
323	     */
324	    @ExceptionHandler(DailyOwnerLimitException.class)
325	    @ResponseBody
326	    public ResponseEntity<ValidationErrorsResponse> handleDailyOwnerLimitException(DailyOwnerLimitException e) {
327	        logger.debug("Daily owner limit reached: {}", e.getMessage());
328	        return ResponseEntity.status(HttpStatus.TOO_MANY_REQUESTS)
329	            .body(new ValidationErrorsResponse(List.of(DailyOwnerLimitException.FIELD)));
330	    }
331	
332	}
