98	
99	    private final HouseholdIdGenerator householdIdGenerator;
100	
101	    private final TelephoneNormalizer telephoneNormalizer;
102	
103	    private final EmailNormalizer emailNormalizer;
104	
105	    private final AddressNormalizer addressNormalizer;
106	
107	    private final CustomerCodeGenerator customerCodeGenerator;
108	
