153	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
154	    @Override
155	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
156	        Collection<Owner> owners;
157	        if (lastName != null) {
158	            owners = this.clinicService.findOwnerByLastName(lastName);
159	        } else {
160	            owners = this.clinicService.findAllOwners();
161	        }
162	        if (owners.isEmpty()) {
163	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
164	        }
165	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
166	    }
