178	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
179	    @Override
180	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
181	        if (ownerFieldsDto != null) {
182	            ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
183	        }
184	        List<String> missingFields = ownerFieldsValidator.findMissingOrBlankFields(ownerFieldsDto);
185	        if (!missingFields.isEmpty()) {
186	            throw new MissingOwnerFieldsException(missingFields);
187	        }
188	        HttpHeaders headers = new HttpHeaders();
189	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
190	        Collection<Owner> sameLastName =
191	            this.clinicService.findOwnersByLastNameIgnoreCase(owner.getLastName());
192	        owner.setNamesakeCount(namesakeCounter.count(owner, sameLastName));
193	        List<Owner> householdMembers = assignHousehold(owner, sameLastName);
194	        owner.setTelephone(telephoneNormalizer.normalize(owner.getTelephone()));
195	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
196	        postcodeValidator.validate(owner.getPostcode(), owner.getCity());
197	        rejectIfDuplicateIdentity(owner);
198	        applyHouseholdRule(owner, ownerFieldsDto, householdMembers, sameLastName);
199	        registrationDateValidator.validate(owner.getRegistrationDate());
200	        if (owner.getRegistrationDate() == null) {
201	            owner.setRegistrationDate(LocalDate.now());
202	        }
203	        owner.setRegistrationDate(BusinessDayResolver.toBusinessDay(owner.getRegistrationDate()));
204	        LocalDate registrationDate = owner.getRegistrationDate();
205	        long ownersRegisteredToday = clinicService.countOwnersByRegistrationDate(registrationDate);
206	        if (ownersRegisteredToday >= DailyOwnerLimitException.MAX_OWNERS_PER_DAY) {
207	            throw new DailyOwnerLimitException(registrationDate);
208	        }
209	        owner.setBulkSignupWarning(bulkSignupWarningEvaluator.isBulkSignup(ownersRegisteredToday));
210	        long cityOwnerCount = clinicService.countOwnersByCity(owner.getCity());
211	        if (cityOwnerCount >= CityOwnerLimitException.MAX_OWNERS_PER_CITY) {
212	            throw new CityOwnerLimitException(owner.getCity());
213	        }
214	        String region = LocalityResolver.localityOf(owner.getPostcode(), owner.getCity());
215	        owner.setCustomerCode(customerCodeGenerator.generate(
216	            region, owner.getTelephone(), owner.getLastName()));
217	        this.clinicService.saveOwner(owner);
218	        ownerAuditLogger.ownerCreated(owner);
219	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
220	        headers.setLocation(UriComponentsBuilder.newInstance()
221	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
222	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
223	    }
224	
225	    /**
226	     * Assigns the household attributes of an owner about to be created, without touching any
227	     * existing owner. The {@code householdId} is derived deterministically from the owner's last
228	     * name and postcode, so every owner in the same household shares it automatically regardless of
229	     * creation order. The new owner's household size after this create is recorded: the existing
230	     * members that share its household (same last name and postcode) plus the owner itself.
231	     *
232	     * @return the existing members of the owner's household (empty when it starts a new household)
233	     */
234	    private List<Owner> assignHousehold(Owner owner, Collection<Owner> sameLastName) {
235	        owner.setHouseholdId(householdIdGenerator.generate(owner));
236	        List<Owner> members = householdDuplicateValidator.findHouseholdMembers(owner, sameLastName);
237	        owner.setHouseholdSize(members.size() + 1);
238	        return members;
239	    }
240	
241	    /**
242	     * Applies the household-membership rule once the owner has cleared hard duplicate detection.
243	     * When the owner joins an existing household (same last name and postcode) it is rejected as a
244	     * household duplicate, unless the request declared {@code sharesHousehold}: a declared member is
245	     * created and, being knowingly registered, is not treated as a suspected duplicate. When the
246	     * owner starts a new household the ordinary possible-duplicate detection runs.
247	     *
248	     * @throws HouseholdDuplicateException if the owner joins an existing household without opting in
249	     */
250	    private void applyHouseholdRule(Owner owner, OwnerFieldsDto ownerFieldsDto,
251	                                    List<Owner> householdMembers, Collection<Owner> sameLastName) {
252	        if (householdMembers.isEmpty()) {
253	            flagPossibleDuplicate(owner, sameLastName);
254	            return;
255	        }
256	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
257	            throw new HouseholdDuplicateException(owner.getHouseholdId());
258	        }
259	        owner.setPossibleDuplicate(false);
260	        owner.setPossibleDuplicateOf(null);
261	    }
262	
263	    /**
264	     * Rejects the owner when its whole derived {@link IdentityKey} already belongs to another
265	     * owner. A full-key match requires an equal telephone, so only owners with the same
266	     * (already normalized) telephone are compared.
267	     *
268	     * @throws DuplicateIdentityException if an existing owner shares the new owner's identity key
269	     */
270	    private void rejectIfDuplicateIdentity(Owner owner) {
271	        Collection<Owner> sameTelephone = this.clinicService.findOwnersByTelephone(owner.getTelephone());
272	        if (identityDuplicateValidator.isDuplicate(owner, sameTelephone)) {
273	            throw new DuplicateIdentityException(IdentityKey.of(owner));
274	        }
275	    }
276	
277	    /**
278	     * Flags the owner as a soft (possible) duplicate when it is not a hard duplicate yet shares an
279	     * existing owner's last name and postcode with a different telephone. The matching owner's id
280	     * is recorded in {@code possibleDuplicateOf}; when nothing matches the owner is stamped as not
281	     * a possible duplicate. Called after {@link #rejectIfDuplicateIdentity(Owner)}, so any candidate
282	     * seen here is guaranteed not to be a hard duplicate.
283	     */
284	    private void flagPossibleDuplicate(Owner owner, Collection<Owner> sameLastName) {
285	        Owner match = possibleDuplicateDetector.findPossibleDuplicate(owner, sameLastName).orElse(null);
286	        owner.setPossibleDuplicate(match != null);
287	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
288	    }
289	
290	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
291	    @Override
292	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
293	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
294	        if (currentOwner == null) {
295	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
296	        }
297	        currentOwner.setAddress(ownerFieldsDto.getAddress());
298	        currentOwner.setCity(ownerFieldsDto.getCity());
299	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
300	        currentOwner.setLastName(ownerFieldsDto.getLastName());
301	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
302	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
303	        this.clinicService.saveOwner(currentOwner);
304	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
305	    }
306	
307	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
308	    @Transactional
309	    @Override
310	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
311	        Owner owner = this.clinicService.findOwnerById(ownerId);
312	        if (owner == null) {
313	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
314	        }
315	        this.clinicService.deleteOwner(owner);
316	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
317	    }
318	
319	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
320	    @Override
321	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
322	        Owner owner = this.clinicService.findOwnerById(ownerId);
323	        if (owner == null) {
324	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
325	        }
326	        HttpHeaders headers = new HttpHeaders();
327	        Pet pet = petMapper.toPet(petFieldsDto);
328	        owner.setId(ownerId);
329	        pet.setOwner(owner);
330	        pet.getType().setName(null);
331	        this.clinicService.savePet(pet);
332	        PetDto petDto = petMapper.toPetDto(pet);
333	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
334	            .buildAndExpand(pet.getId()).toUri());
335	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
336	    }
337	
338	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
339	    @Override
340	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
341	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
342	        if (currentOwner != null) {
343	            Pet currentPet = this.clinicService.findPetById(petId);
344	            if (currentPet != null) {
345	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
346	                currentPet.setName(petFieldsDto.getName());
347	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
348	                this.clinicService.savePet(currentPet);
349	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
350	            }
351	        }
352	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
353	    }
354	
355	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
356	    @Override
357	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
358	        HttpHeaders headers = new HttpHeaders();
359	        Visit visit = visitMapper.toVisit(visitFieldsDto);
360	        Pet pet = new Pet();
361	        pet.setId(petId);
362	        visit.setPet(pet);
363	        this.clinicService.saveVisit(visit);
364	        VisitDto visitDto = visitMapper.toVisitDto(visit);
365	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
366	            .buildAndExpand(visit.getId()).toUri());
367	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
368	    }
369	
370	
371	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
372	    @Override
373	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
374	        Owner owner = this.clinicService.findOwnerById(ownerId);
375	        if (owner != null) {
376	            Pet pet = owner.getPet(petId);
377	            if (pet != null) {
378	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
379	            }
380	        }
381	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
382	    }
383	}
