180	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
181	        if (ownerFieldsDto != null) {
182	            ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
183	        }
184	        List<String> missingFields = ownerFieldsValidator.findMissingOrBlankFields(ownerFieldsDto);
185	        if (!missingFields.isEmpty()) {
186	            throw new MissingOwnerFieldsException(missingFields);
187	        }
188	        HttpHeaders headers = new HttpHeaders();
189	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
190	        Collection<Owner> sameLastName =
191	            this.clinicService.findOwnersByLastNameIgnoreCase(owner.getLastName());
192	        owner.setNamesakeCount(namesakeCounter.count(owner, sameLastName));
193	        List<Owner> householdMembers = assignHousehold(owner, sameLastName);
194	        owner.setTelephone(telephoneNormalizer.normalize(owner.getTelephone()));
195	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
196	        postcodeValidator.validate(owner.getPostcode(), owner.getCity());
197	        rejectIfDuplicateIdentity(owner);
198	        applyHouseholdRule(owner, ownerFieldsDto, householdMembers, sameLastName);
199	        registrationDateValidator.validate(owner.getRegistrationDate());
200	        if (owner.getRegistrationDate() == null) {
201	            owner.setRegistrationDate(LocalDate.now());
202	        }
203	        owner.setRegistrationDate(BusinessDayResolver.toBusinessDay(owner.getRegistrationDate()));
204	        LocalDate registrationDate = owner.getRegistrationDate();
205	        long ownersRegisteredToday = clinicService.countOwnersByRegistrationDate(registrationDate);
206	        if (ownersRegisteredToday >= DailyOwnerLimitException.MAX_OWNERS_PER_DAY) {
207	            throw new DailyOwnerLimitException(registrationDate);
208	        }
209	        owner.setBulkSignupWarning(bulkSignupWarningEvaluator.isBulkSignup(ownersRegisteredToday));
210	        long cityOwnerCount = clinicService.countOwnersByCity(owner.getCity());
211	        if (cityOwnerCount >= CityOwnerLimitException.MAX_OWNERS_PER_CITY) {
212	            throw new CityOwnerLimitException(owner.getCity());
213	        }
214	        String region = LocalityResolver.localityOf(owner.getPostcode(), owner.getCity());
215	        owner.setCustomerCode(customerCodeGenerator.generate(
216	            region, owner.getTelephone(), owner.getLastName()));
217	        this.clinicService.saveOwner(owner);
218	        ownerAuditLogger.ownerCreated(owner);
219	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
220	        headers.setLocation(UriComponentsBuilder.newInstance()
221	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
222	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
223	    }
