225	    /**
226	     * Assigns the household attributes of an owner about to be created, without touching any
227	     * existing owner. The {@code householdId} is derived deterministically from the owner's last
228	     * name and postcode, so every owner in the same household shares it automatically regardless of
229	     * creation order. The new owner's household size after this create is recorded: the existing
230	     * members that share its household (same last name and postcode) plus the owner itself.
231	     *
232	     * @return the existing members of the owner's household (empty when it starts a new household)
233	     */
234	    private List<Owner> assignHousehold(Owner owner, Collection<Owner> sameLastName) {
235	        owner.setHouseholdId(householdIdGenerator.generate(owner));
236	        List<Owner> members = householdDuplicateValidator.findHouseholdMembers(owner, sameLastName);
237	        owner.setHouseholdSize(members.size() + 1);
238	        return members;
239	    }
240	
241	    /**
242	     * Applies the household-membership rule once the owner has cleared hard duplicate detection.
243	     * When the owner joins an existing household (same last name and postcode) it is rejected as a
244	     * household duplicate, unless the request declared {@code sharesHousehold}: a declared member is
245	     * created and, being knowingly registered, is not treated as a suspected duplicate. When the
246	     * owner starts a new household the ordinary possible-duplicate detection runs.
247	     *
248	     * @throws HouseholdDuplicateException if the owner joins an existing household without opting in
249	     */
250	    private void applyHouseholdRule(Owner owner, OwnerFieldsDto ownerFieldsDto,
251	                                    List<Owner> householdMembers, Collection<Owner> sameLastName) {
252	        if (householdMembers.isEmpty()) {
253	            flagPossibleDuplicate(owner, sameLastName);
254	            return;
255	        }
256	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
257	            throw new HouseholdDuplicateException(owner.getHouseholdId());
258	        }
259	        owner.setPossibleDuplicate(false);
260	        owner.setPossibleDuplicateOf(null);
261	    }
262	
263	    /**
264	     * Rejects the owner when its whole derived {@link IdentityKey} already belongs to another
265	     * owner. A full-key match requires an equal telephone, so only owners with the same
266	     * (already normalized) telephone are compared.
267	     *
268	     * @throws DuplicateIdentityException if an existing owner shares the new owner's identity key
269	     */
270	    private void rejectIfDuplicateIdentity(Owner owner) {
271	        Collection<Owner> sameTelephone = this.clinicService.findOwnersByTelephone(owner.getTelephone());
272	        if (identityDuplicateValidator.isDuplicate(owner, sameTelephone)) {
273	            throw new DuplicateIdentityException(IdentityKey.of(owner));
274	        }
275	    }
276	
277	    /**
278	     * Flags the owner as a soft (possible) duplicate when it is not a hard duplicate yet shares an
279	     * existing owner's last name and postcode with a different telephone. The matching owner's id
280	     * is recorded in {@code possibleDuplicateOf}; when nothing matches the owner is stamped as not
281	     * a possible duplicate. Called after {@link #rejectIfDuplicateIdentity(Owner)}, so any candidate
282	     * seen here is guaranteed not to be a hard duplicate.
283	     */
284	    private void flagPossibleDuplicate(Owner owner, Collection<Owner> sameLastName) {
285	        Owner match = possibleDuplicateDetector.findPossibleDuplicate(owner, sameLastName).orElse(null);
286	        owner.setPossibleDuplicate(match != null);
287	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
288	    }
